/bin/zsh -lc "python3 - <<'PY'
import json
from collections import Counter
from pathlib import Path
source=json.loads(Path('declarations.json').read_text())
result=json.loads(Path('out/declarations.json').read_text())
passages={p['id'] for p in map(json.loads,Path('passages.jsonl').read_text().splitlines())}
assert Counter(r['id'] for r in result)==Counter(d['id'] for d in source)
assert len(result)==len({r['id'] for r in result})==298
for r in result:
 assert set(r)=={'id','kind','matches','tension','notes'}
 assert r['kind'] in {'syntax_definition','representation','derived_property','operational_model','unclear'}
 assert isinstance(r['notes'],str) and isinstance(r['matches'],list)
 for m in r['matches']:
  assert set(m)=={'passage','relation'}
  assert m['passage'] in passages
  assert m['relation'] in {'defines','uses','version_difference'}
 if r['tension'] is not None:
  assert set(r['tension'])=={'passages','description'}
  assert isinstance(r['tension']['description'],str)
  assert all(p in passages for p in r['tension']['passages'])
print('Validation passed: valid JSON; 298 distinct declarations; exact input coverage; all match and tension passage IDs exist.')
print('Output files:', ', '.join(str(p) for p in Path('out').iterdir()))
PY"
